import{_ as t,o as i,c as a,ag as l}from"./chunks/framework.BS9hZhOX.js";const h=JSON.parse('{"title":"安徽机房","description":"","frontmatter":{},"headers":[],"relativePath":"notes/ahjf.md","filePath":"notes/ahjf.md"}'),r={name:"notes/ahjf.md"};function c(o,e,n,s,p,y){return i(),a("div",null,[...e[0]||(e[0]=[l('<h1 id="安徽机房" tabindex="-1">安徽机房 <a class="header-anchor" href="#安徽机房" aria-label="Permalink to &quot;安徽机房&quot;">​</a></h1><h2 id="安徽机房功能梳理" tabindex="-1">安徽机房功能梳理 <a class="header-anchor" href="#安徽机房功能梳理" aria-label="Permalink to &quot;安徽机房功能梳理&quot;">​</a></h2><h3 id="能耗统计" tabindex="-1">能耗统计 <a class="header-anchor" href="#能耗统计" aria-label="Permalink to &quot;能耗统计&quot;">​</a></h3><p><strong>1. 定时采集与落库（用电统计主链）</strong> 入口是 EnergyStatisticsTask.java (line 68)，每小时整点跑一次。流程是：先按设备类型拆两批设备（配电 54，IT 50/53）EnergyStatisticsTask.java (line 73)，月初零点先归档上月数据 EnergyStatisticsTask.java (line 80)，再并发调用服务采集 EnergyStatisticsTask.java (line 86)。</p><p>单设备采集在 ElectricityServiceImpl.java (line 265)：</p><ul><li>配电取点位“组合有功总电能”，IT取两路进线累计点位 ElectricityServiceImpl.java (line 95)。</li><li>从 df_jk_yc 取最新点位，按点位名去重并汇总成当前累计电能快照（totalEnergy + collectTime）ElectricityServiceImpl.java (line 363)。</li><li>增量电量 = currentTotal - lastTotal，负值直接置 0 ElectricityServiceImpl.java (line 509)。</li><li>周期判断用“上次采集日期 vs 本次采集日期”计算跨天/跨周/跨月（不再依赖 hour==0）ElectricityServiceImpl.java (line 751)。</li><li>日序列是固定 24 槽，按采集小时写到对应索引 ElectricityServiceImpl.java (line 537)。</li><li>周/月序列存“当天累计值”，跨天先补槽，再回写最后一个槽位 ElectricityServiceImpl.java (line 342)。</li></ul><p>月归档逻辑在 EnergyStatisticsTask.java (line 99)：取 df_electricity_statistics 当前 energy_monthly_kwh 求和，写入 his_rack_statistics。</p><p><strong>2. 用电量查询（getElectricityStatistics）</strong> 查询入口在 ElectricityServiceImpl.java (line 196)。按机房取 df_electricity_statistics 所有设备后：</p><ul><li>dailyElectricity：把各设备 energy_daily_kwh 按索引求和，再裁剪到“当天 0 点到当前时刻” ElectricityServiceImpl.java (line 225)。</li><li>weeklyElectricity：按索引求和后裁剪到“周一到前一天” ElectricityServiceImpl.java (line 228)。</li><li>monthlyElectricity：按索引求和后裁剪到“每月1号到前一天” ElectricityServiceImpl.java (line 231)。</li><li>同时返回 lastMonthlyElectricity（上月序列）和 monthlyCurrentElectricity（本月累计）ElectricityServiceImpl.java (line 234)。</li></ul><p><strong>3. PUE 查询（getEnergyStatistics）</strong> PUE 查询入口在 ElectricityServiceImpl.java (line 125)。</p><ul><li>分子（总电）取设备类型 54，分母（IT电）取 50/53 ElectricityServiceImpl.java (line 137)。</li><li>当前 pue 用 last_total_energy_kwh 汇总计算：pue = totalLastTotal / itLastTotal ElectricityServiceImpl.java (line 155)。</li><li>趋势 daily/weekly/monthlyPueTrend 是先把两类设备序列按索引汇总，再逐点 total/it 计算，并按时间窗口裁剪 ElectricityServiceImpl.java (line 145) ElectricityServiceImpl.java (line 449)。</li></ul><p>核心上，当前系统是“双口径并存”：</p><ul><li>当前值（瞬时）看 last_total_energy_kwh；</li><li>趋势看日/周/月字符串序列。</li></ul><h2 id="安徽机房项目踩坑" tabindex="-1">安徽机房项目踩坑 <a class="header-anchor" href="#安徽机房项目踩坑" aria-label="Permalink to &quot;安徽机房项目踩坑&quot;">​</a></h2><h3 id="jsonformat注解在beanutils-copyproperties-方法中会失效" tabindex="-1">@JsonFormat注解在BeanUtils.copyProperties()方法中会失效 <a class="header-anchor" href="#jsonformat注解在beanutils-copyproperties-方法中会失效" aria-label="Permalink to &quot;@JsonFormat注解在BeanUtils.copyProperties()方法中会失效&quot;">​</a></h3><h5 id="核心原理" tabindex="-1">核心原理： <a class="header-anchor" href="#核心原理" aria-label="Permalink to &quot;核心原理：&quot;">​</a></h5><p>让我们来解析一下两个工具的工作机制：</p><ul><li><strong>@JsonFormat 的工作方式</strong>：它的功能由 Jackson 库实现。只有当您使用 <code>ObjectMapper</code>（如 <code>objectMapper.writeValueAsString(obj)</code>）将对象序列化为 JSON 字符串时，Jackson 才会去读取这个注解，并按照您指定的 <code>pattern</code>（如 <code>yyyy-MM-dd HH:mm:ss</code>）来格式化时间字段。</li><li><strong>BeanUtils.copyProperties() 的工作方式</strong>：这个方法通过 Java 反射机制工作。它会找到源对象和目标对象中<strong>同名的属性</strong>，然后调用属性的 <code>getXxx()</code> 方法从源对象读取值，再调用 <code>setXxx()</code> 方法将值写入目标对象。这个过程完全是内存中的字段值拷贝，<strong>既不涉及 JSON 转换，也不会检查和解析任何 Jackson 相关的注解</strong>。</li></ul>',18)])])}const m=t(r,[["render",c]]);export{h as __pageData,m as default};
